mapper.select:
SELECT 
FROM SF_RESOURCE_STOCK S
JOIN SF_DEPARTMENT D ON D.DEPARTMENT_ID = S.DEPARTMENT_ID
JOIN SF_RESOURCE_ITEM I ON I.ITEM_ID = S.ITEM_ID


        S.STATUS = 'ACTIVE'


        AND S.DEPARTMENT_ID = #{departmentId}


        AND S.ITEM_ID = #{itemId}


        AND I.CATEGORY = #{category}


ORDER BY S.DEPARTMENT_ID, S.ITEM_ID
